struct SurfBoardObjectClass {
  char data[1];
  void Turn(int, float, float, float) __asm__("Turn__20SurfBoardObjectClass14BoardStateEnumfff");
};
struct game { char pad[552]; int beach_id; int get_beach_id() { return beach_id; } };
struct BeachData { char pad[208]; int bdir; char tail[320]; };
extern game *g_game_ptr;
extern BeachData BeachDataArray[];
__asm__(".equ g_game_ptr,0x0046AC64");
__asm__(".equ BeachDataArray,0x0043C198");
__asm__(".equ Turn__20SurfBoardObjectClass14BoardStateEnumfff,0x001EFC60");
__asm__(".equ Anim__22kellyslater_controllerifbfT3,0x00212660");
__asm__(".equ BoardAnim__22kellyslater_controllerifbf,0x002128B0");
__asm__(".equ AnimComplete__22kellyslater_controller,0x00212D78");
__asm__(".equ StandAnim__22kellyslater_controller,0x00224B60");
enum { BEACH_COSMOS=13, STATE_CELEBRATE=90, STATE_DISAPPOINTED=91, STATE_DONTCELEBRATE=92, STATE_CELEBRATERAILGRAB=93, BOARD_TURN_RIGHT=4, SURFER_ANIM_BAS_CEL_01=359, SURFER_ANIM_BAS_CELNOT_01=360, SURFER_ANIM_BAS_DIS_01=361, SURFER_ANIM_TRK_TUBE_GRAB_L_1=116, SURFER_ANIM_TRK_TUBE_GRAB_R_1=109, BOARD_ANIM_ZERO=0 };
const float BLEND_TIME=0.3f;
class kellyslater_controller {
  char pad0[48]; int state; int last_state; char pad1[428]; int goofy; char pad2[404];
  SurfBoardObjectClass my_board_controller; char pad3[4883]; bool done_scoring; char pad4[39]; bool bSpecialTrick; char pad5[3]; float rideTimer; char pad6[624]; bool exit_state; char pad7[587]; bool did_celebration; char pad8[3]; bool IK_enabled;
public:
  void SuperStateCPUControlled(float);
  void Anim(int,float,bool=true,float=0.0f,bool=false) __asm__("Anim__22kellyslater_controllerifbfT3");
  void BoardAnim(int,float,bool=true,float=0.0f) __asm__("BoardAnim__22kellyslater_controllerifbf");
  bool AnimComplete() __asm__("AnimComplete__22kellyslater_controller");
  int StandAnim() __asm__("StandAnim__22kellyslater_controller");
};
void kellyslater_controller::SuperStateCPUControlled(float dt) 
{
	if (last_state != state)
	{
		bSpecialTrick = false;
		rideTimer = 0.0f;
		int current_beach = g_game_ptr->get_beach_id ();
		if ((current_beach == BEACH_COSMOS) && (state != STATE_CELEBRATERAILGRAB))
			state = STATE_DONTCELEBRATE;

		// Straighten him up.  (dc 03/27/02)
		my_board_controller.Turn(BOARD_TURN_RIGHT, 0.0f, dt);

		switch (state)
		{
		case STATE_CELEBRATE:
				Anim(SURFER_ANIM_BAS_CEL_01, BLEND_TIME, false);
				BoardAnim(BOARD_ANIM_ZERO, 0.0f, false);
			break;

		case STATE_DONTCELEBRATE:
				Anim(SURFER_ANIM_BAS_CELNOT_01, BLEND_TIME, false);
				BoardAnim(BOARD_ANIM_ZERO, 0.0f, false);
			break;

		case STATE_DISAPPOINTED:
				Anim(SURFER_ANIM_BAS_DIS_01, BLEND_TIME, false);
				BoardAnim(BOARD_ANIM_ZERO, 0.0f, false);
			break;
		case STATE_CELEBRATERAILGRAB:
			{
				bool left_wave = BeachDataArray[g_game_ptr->get_beach_id ()].bdir;

				//  Always grab the outside rail.
				if ((left_wave && !goofy) || (!left_wave && goofy))  
					Anim(SURFER_ANIM_TRK_TUBE_GRAB_L_1, BLEND_TIME, false);
				else
					Anim(SURFER_ANIM_TRK_TUBE_GRAB_R_1, BLEND_TIME, false);
				BoardAnim(BOARD_ANIM_ZERO, BLEND_TIME, false);
			}
			break;

		default:
			break;
		}
	}

	last_state = state;

	if (AnimComplete() || (state == STATE_CELEBRATERAILGRAB))
	{
		done_scoring = true;
		did_celebration = true;
		IK_enabled = true;
		Anim(StandAnim(), BLEND_TIME);
		BoardAnim(BOARD_ANIM_ZERO, 0.0f, false);
	}

	exit_state = true;
}
